// Migration of the boltons.dictutils subset used by the original script:
// OrderedMultiDict (OMD), dict(omd) conversion, and FrozenDict.
import { PyDict, PyTuple, pyRepr } from './pyvalues.mjs';

// OrderedMultiDict: stores every added (key, value) pair in insertion
// order; duplicate keys are allowed. keys() yields each unique key once,
// in first-seen order (uniqueness follows Python key equality via PyDict).
export class OMD {
  constructor() {
    this._pairs = [];
  }

  add(k, v) {
    this._pairs.push([k, v]);
  }

  keys() {
    const seen = new PyDict();
    for (const [k] of this._pairs) {
      if (!seen.has(k)) {
        seen.set(k, true);
      }
    }
    return seen.keys();
  }

  __pyRepr__() {
    if (this._pairs.length === 0) {
      return 'OrderedMultiDict([])';
    }
    const parts = this._pairs.map(([k, v]) => pyRepr(new PyTuple([k, v])));
    return 'OrderedMultiDict([' + parts.join(', ') + '])';
  }
}

// Replicates Python dict(omd): replay all pairs in order; duplicate keys
// keep their first-seen position, but the LAST value wins.
export function dictFromOMD(omd) {
  const d = new PyDict();
  for (const [k, v] of omd._pairs) {
    d.set(k, v);
  }
  return d;
}

// FrozenDict: immutable snapshot of a PyDict taken at construction time.
// Insertion (key) order is preserved.
export class FrozenDict {
  constructor(pyDict) {
    this._entries = pyDict.items().map((t) => [t.items[0], t.items[1]]);
  }

  keys() {
    return this._entries.map(([k]) => k);
  }

  values() {
    return this._entries.map(([, v]) => v);
  }

  items() {
    return this._entries.map(([k, v]) => new PyTuple([k, v]));
  }

  __pyRepr__() {
    return 'FrozenDict(' + pyRepr(new PyDict(this._entries)) + ')';
  }
}

// Minimal stub of /output/lib/pyvalues.mjs for scratch-testing dictutils only.
export class PyFloat {
  constructor(value) { this.value = value; }
}
export class PyTuple {
  constructor(items) { this.items = items; }
}
function keyId(k) {
  if (k === true) return 'n:1';
  if (k === false) return 'n:0';
  if (typeof k === 'number') return 'n:' + k;
  if (k instanceof PyFloat) return 'n:' + k.value;
  if (typeof k === 'string') return 's:' + k;
  return 'o:' + String(k);
}
export class PyDict {
  constructor(entries) {
    this._map = new Map();
    if (entries) for (const [k, v] of entries) this.set(k, v);
  }
  set(k, v) {
    const id = keyId(k);
    if (this._map.has(id)) this._map.get(id)[1] = v;
    else this._map.set(id, [k, v]);
  }
  get(k) { const e = this._map.get(keyId(k)); return e && e[1]; }
  has(k) { return this._map.has(keyId(k)); }
  keys() { return [...this._map.values()].map(([k]) => k); }
  values() { return [...this._map.values()].map(([, v]) => v); }
  items() { return [...this._map.values()].map(([k, v]) => new PyTuple([k, v])); }
  get size() { return this._map.size; }
}
export function pyFloatRepr(x) { return String(x); }
export function pyRepr(v) {
  if (v instanceof PyFloat) return pyFloatRepr(v.value);
  if (typeof v === 'number') return String(v);
  if (typeof v === 'boolean') return v ? 'True' : 'False';
  if (v === null || v === undefined) return 'None';
  if (typeof v === 'string') return "'" + v.replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
  if (Array.isArray(v)) return '[' + v.map(pyRepr).join(', ') + ']';
  if (v instanceof PyTuple) {
    if (v.items.length === 0) return '()';
    if (v.items.length === 1) return '(' + pyRepr(v.items[0]) + ',)';
    return '(' + v.items.map(pyRepr).join(', ') + ')';
  }
  if (v instanceof PyDict) {
    const parts = v.items().map((t) => pyRepr(t.items[0]) + ': ' + pyRepr(t.items[1]));
    return '{' + parts.join(', ') + '}';
  }
  if (v && typeof v.__pyRepr__ === 'function') return v.__pyRepr__();
  return String(v);
}

import { OMD, dictFromOMD, FrozenDict } from './dictutils.mjs';
import { PyDict, PyTuple, PyFloat, pyRepr } from './pyvalues.mjs';

let failures = 0;
function eq(actual, expected, label) {
  if (actual !== expected) {
    failures++;
    console.log(`FAIL ${label}: got ${actual}, want ${expected}`);
  } else {
    console.log(`ok   ${label}`);
  }
}

// Empty OMD repr
const omd0 = new OMD();
eq(pyRepr(omd0), 'OrderedMultiDict([])', 'empty OMD repr');
eq(JSON.stringify(omd0.keys()), '[]', 'empty OMD keys');

// Verified scenario from the contract:
// adds (key_0,10),(key_1,-3),(key_2,7),(key_0,2.5),(key_1,-8)
const omd = new OMD();
omd.add('key_0', 10);
omd.add('key_1', -3);
omd.add('key_2', 7);
omd.add('key_0', new PyFloat(2.5));
omd.add('key_1', -8);

eq(JSON.stringify(omd.keys()), '["key_0","key_1","key_2"]', 'OMD keys unique first-seen');
eq(pyRepr(omd), "OrderedMultiDict([('key_0', 10), ('key_1', -3), ('key_2', 7), ('key_0', 2.5), ('key_1', -8)])", 'OMD repr');

// dictFromOMD: last value wins, first-seen position
const d = dictFromOMD(omd);
eq(pyRepr(d), "{'key_0': 2.5, 'key_1': -8, 'key_2': 7}", 'dictFromOMD');

// FrozenDict
const fd = new FrozenDict(d);
eq(pyRepr(fd), "FrozenDict({'key_0': 2.5, 'key_1': -8, 'key_2': 7})", 'FrozenDict repr');
eq(JSON.stringify(fd.keys()), '["key_0","key_1","key_2"]', 'FrozenDict keys');
eq(pyRepr(fd.items()), "[('key_0', 2.5), ('key_1', -8), ('key_2', 7)]", 'FrozenDict items are PyTuples');
eq(fd.items()[0] instanceof PyTuple, true, 'FrozenDict items element type');

// Empty FrozenDict
eq(pyRepr(new FrozenDict(new PyDict())), 'FrozenDict({})', 'empty FrozenDict repr');

// Snapshot semantics: mutating source dict after construction must not affect FrozenDict
d.set('key_0', 999);
d.set('extra', 1);
eq(pyRepr(fd), "FrozenDict({'key_0': 2.5, 'key_1': -8, 'key_2': 7})", 'FrozenDict is a snapshot');

// Result17-style: FrozenDict built from another FrozenDict's items
const d17 = new PyDict(fd.items().map((t) => [t.items[0], String(t.items[1]).length]));
const fd17 = new FrozenDict(d17);
eq(pyRepr(fd17), "FrozenDict({'key_0': 3, 'key_1': 2, 'key_2': 1})", 'FrozenDict comprehension-style build');

// Single-pair OMD repr (tuple repr inside list, no trailing comma in list)
const omd1 = new OMD();
omd1.add('a', 1);
eq(pyRepr(omd1), "OrderedMultiDict([('a', 1)])", 'single-pair OMD repr');

process.exit(failures ? 1 : 0);
